"""Static `terraform/*.tf` boilerplate `plan` writes alongside plugin-generated files
(spec §5.2 "Output files", plan 4 B2 step 6): providers.tf, backend.tf, variables.tf
and terraform.tfvars.

The Google provider major version is pinned here; re-check it against
`gh api repos/hashicorp/terraform-provider-google/releases/latest` occasionally.
"""

from __future__ import annotations

from easymigrate.providers.gcp.hcl import HclFile, Ref, escape

GOOGLE_PROVIDER_VERSION = "~> 8.0"

_HEADER = "Generated by EasyMigrate {version}. Do not edit by hand; re-run easymigrate plan."


def _header(version: str) -> list[str]:
    return [_HEADER.format(version=version)]


def render_providers_tf(version: str) -> str:
    file = HclFile(header=_header(version))
    tf = file.block("terraform")
    rp = tf.block("required_providers")
    rp.attr("google", {"source": "hashicorp/google", "version": GOOGLE_PROVIDER_VERSION})
    # Without this block the provider has no project and every resource fails at plan time
    # with "project: required field is not set" (found by the first live run).
    google = file.block("provider", "google")
    google.attr("project", Ref("var.project"))
    google.attr("region", Ref("var.region"))
    return file.render()


def render_backend_tf(version: str) -> str:
    file = HclFile(header=_header(version))
    tf = file.block("terraform")
    tf.block("backend", "gcs")
    return file.render()


def render_variables_tf(version: str) -> str:
    file = HclFile(header=_header(version))
    project = file.block("variable", "project")
    project.attr("type", Ref("string"))
    region = file.block("variable", "region")
    region.attr("type", Ref("string"))
    return file.render()


def render_tfvars(gcp_project: str, gcp_region: str, version: str) -> str:
    lines = [f"# {line}" for line in _header(version)]
    lines.append("")
    lines.append(f'project = "{escape(gcp_project)}"')
    lines.append(f'region  = "{escape(gcp_region)}"')
    return "\n".join(lines) + "\n"
